$error=null;$m=['legacy'=>0,'products'=>0,'users'=>0,'sessions'=>0,'journals'=>0,'cash_accounts'=>0,'receivable'=>0.0,'supplier_due'=>0.0,'stock'=>0.0,'backups'=>0,'verified'=>0,'environment'=>'local','deploy_health'=>'review','releases'=>0,'offsite'=>0];
try{$pdo=business_db();$user=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$canFinance=security_step17_has_permission($pdo,'finance.view',$user);$canCustomers=security_step17_has_permission($pdo,'customers.view',$user);$canPurchases=security_step17_has_permission($pdo,'purchases.view',$user);$canInventory=security_step17_has_permission($pdo,'inventory.view',$user);$canSecurity=security_step17_has_permission($pdo,'security.audit.view',$user);$canAudit=security_step17_has_permission($pdo,'audit.view',$user);$canBackup=security_step17_has_permission($pdo,'backup.view',$user);$canDeploy=security_step17_has_permission($pdo,'deployment.view',$user);$s=$pdo->prepare("SELECT SUM(mapping_status='mapped') FROM raw_source_records WHERE organization_id=? AND source_dataset IN ('New UMS','Volume Points','First & Second Set','Active UMS Month_Wise','Renewal UMS','Monthely_Income','Royalty_Tracking','Extra Order for Customer')");$s->execute([$orgId]);$m['legacy']=(int)$s->fetchColumn();if(business_table_exists($pdo,'products')){$s=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$m['products']=(int)$s->fetchColumn();}if($canSecurity){$s=$pdo->prepare("SELECT COUNT(*) FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.is_active=1 AND a.is_active=1");$s->execute([$orgId]);$m['users']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM security_sessions WHERE organization_id=? AND revoked_at IS NULL AND expires_at>NOW()");$s->execute([$orgId]);$m['sessions']=(int)$s->fetchColumn();}if($canFinance){finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$s=$pdo->prepare("SELECT COUNT(*) FROM finance_journals WHERE organization_id=?");$s->execute([$orgId]);$m['journals']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM finance_cash_accounts WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$m['cash_accounts']=(int)$s->fetchColumn();}if($canCustomers&&business_table_exists($pdo,'sales_fulfillment_ledger')){$s=$pdo->prepare("SELECT COALESCE(SUM(receivable_amount),0) FROM sales_fulfillment_ledger f JOIN product_sale_ledger sl ON sl.organization_id=f.organization_id AND sl.order_id=f.order_id WHERE f.organization_id=? AND sl.sale_status='active'");$s->execute([$orgId]);$m['receivable']=(float)$s->fetchColumn();}if($canPurchases&&business_table_exists($pdo,'purchase_bills')){foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['supplier_due']+=(float)$st['outstanding'];}}if($canInventory&&business_table_exists($pdo,'inventory_locations')){$loc=inventory_step13_location_id($pdo,$orgId);foreach(inventory_step13_stock_rows($pdo,$orgId,$loc) as $r)$m['stock']+=(float)$r['sellable_stock'];}if($canBackup){backup_step18_ensure($pdo);$s=$pdo->prepare("SELECT COUNT(*) total,SUM(verification_status='verified' AND status<>'expired') verified FROM backup_records WHERE organization_id=?");$s->execute([$orgId]);$r=$s->fetch()?:[];$m['backups']=(int)($r['total']??0);$m['verified']=(int)($r['verified']??0);}if($canDeploy){deployment_step19_ensure($pdo);$health=deployment_step19_health($pdo,false);$m['environment']=deployment_step19_env();$m['deploy_health']=$health['status'];$s=$pdo->prepare("SELECT COUNT(*) FROM deployment_releases WHERE organization_id=?");$s->execute([$orgId]);$m['releases']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM deployment_offsite_targets WHERE organization_id=? AND is_enabled=1 AND last_status='pass'");$s->execute([$orgId]);$m['offsite']=(int)$s->fetchColumn();}}catch(Throwable $e){$error=$e->getMessage();}
function d19m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function d19n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
